INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'first-of-three-supermoons-rises-over-pretoria-2026-11-20',
  'First of three supermoons rises over Pretoria on Tuesday',
  'Community', '2026-11-20', 'Rekord', 'https://www.citizen.co.za/rekord/news-headlines/2026/11/20/supermoon-to-rise-over-pretoria-next-week-heres-when-to-look-up/',
  'The year''s first of three consecutive supermoons turns full over Pretoria on Tuesday evening, with moonrise about ten minutes after sunset.',
  'Pretoria residents will get their first chance this week to see a supermoon, as the Moon reaches its fullest point at 16:53 on Tuesday, 24 November, according to the Wits Anglo American Digital Dome. A supermoon happens when the Moon becomes full while sitting close to Earth in its orbit, which is what makes it look noticeably larger and brighter than usual.

Pretoria''s moonrise falls at 18:49 that evening, only a short while after sunset, so the Moon should look practically full as soon as it clears the horizon. Stargazers are advised to find a spot with a clear view toward the east-northeast, away from tall buildings and trees that could block the view. Those who miss Tuesday can still see a nearly full moon on Monday evening.

This particular full moon carries the folk name Beaver Moon, which the Old Farmer''s Almanac links to the season when North American beavers get ready for the colder months ahead. NASA and several astronomy sites describe this as the first of three consecutive supermoons, with the next two expected in December and January.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/news-headlines/2026/11/20/supermoon-to-rise-over-pretoria-next-week-heres-when-to-look-up/", "https://www.space.com/stargazing/november-full-moon-2026-when-where-and-how-to-see-the-beaver-moon"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'john-legend-adds-second-pretoria-show-2026-11-16',
  'John Legend adds second Pretoria show to 2027 tour',
  'Tourism', '2026-11-16', 'Time Out Pretoria', 'https://www.timeout.com/pretoria/news/john-legend-111626',
  'Strong ticket demand has pushed John Legend to add extra Pretoria and Cape Town dates to his Muse Tour in February 2027.',
  'International R&B star John Legend has added extra Pretoria and Cape Town shows to his Muse Tour of South Africa after tickets for the original dates sold quickly. The tour, first announced in early November, now gives fans in Gauteng and the Western Cape two chances each to see him live in February 2027.

Legend''s South African leg opens in Pretoria, with shows now set for 20 and 21 February at the SunBet Arena at Time Square. He then travels to Durban''s ICC on 23 February, before closing the tour with two Cape Town performances at the Grand Arena at GrandWest on 25 and 26 February.

Tickets went on sale through Ticketmaster from Friday, 13 November, with seated prices starting at R970. Organisers say the extra shows were added because of how fast the original dates sold once the tour was announced. Legend''s set is expected to draw on his new album, Muse, alongside long-time favourites such as "All of Me" and "Ordinary People."',
  NULL, NULL, NULL,
  '["https://www.timeout.com/pretoria/news/john-legend-111626", "https://www.ewn.co.za/2026/11/11/im-coming-back-to-see-you-john-legend-brings-the-muse-tour-to-sa-in-feb-2027"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'uncle-waffles-opens-for-tyla-pretoria-2026-11-18',
  'Uncle Waffles to open for Tyla''s Pretoria shows in January',
  'Tourism', '2026-11-18', 'Time Out Pretoria', 'https://www.timeout.com/pretoria/news/tyla-111826',
  'Grammy winner Tyla has confirmed Uncle Waffles as her support act for two A*POP World Tour shows in Pretoria in January 2027.',
  'Pretoria fans now know who will open for Tyla when her A*POP World Tour reaches the city in January 2027. Organisers have confirmed Eswatini-born performer Uncle Waffles, real name Lungelihle Zwane, as the headline support act for both Pretoria shows, alongside the tour''s earlier Cape Town date.

Tyla plays Cape Town''s Green Point Track on 4 January before two nights at Pretoria''s SunBet Arena on 8 and 9 January, with a second Pretoria date added earlier this year because of demand. Three further acts round out the lineup in both cities: Ez Maestro, Optimist Music ZA and Babalwa M. Liquideep is billed as a special guest at every show, and MaWhoo is set to perform only at the Cape Town date.

Tickets for the Cape Town show are sold through Howler, while the Pretoria concerts are being sold exclusively through Ticketmaster South Africa. Every show has a minimum entry age of six, and the standing Golden Circle sections additionally require ticket holders to stand 1.2 metres tall and be 12 years of age or older.',
  NULL, NULL, NULL,
  '["https://www.timeout.com/pretoria/news/tyla-111826", "https://www.capetownetc.com/lifestyle/tyla-announces-uncle-waffles-as-special-guest-for-cape-town-concert/"]',
  'agent'
);
